package ai.decisionos.aside;
import android.app.*;import android.os.*;import android.content.*;import org.json.*;
final class SchoolChatChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;String id="";try(GoalStore store=new GoalStore(i.getTargetContext())){
  i.check(SchoolSignIn.allowed("https://fs.unist.ac.kr/adfs/ls/"),"ADFS allowed");i.check(SchoolSignIn.allowed("https://login.microsoftonline.com/common/oauth2/authorize"),"Microsoft allowed");
  for(String url:new String[]{"http://portal.unist.ac.kr","https://unist.ac.kr.evil.com","https://evilunist.ac.kr","file:///data/test","javascript:alert(1)"})i.check(!SchoolSignIn.allowed(url),"unsafe auth navigation rejected "+url);
  i.check(!SchoolSignIn.verified("portal","https://portal.unist.ac.kr/",false,false),"page open not login");i.check(!SchoolSignIn.verified("portal","https://portal.unist.ac.kr/",true,true),"login form not verified");i.check(!SchoolSignIn.verified("mail","https://login.microsoftonline.com/",false,true),"identity provider not mail connection");i.check(SchoolSignIn.verified("mail","https://outlook.office.com/mail/",false,true),"mail application evidence");
  id=store.create("grades","REGRESSION_SCHOOL_CHAT","학교",0).optString("id");a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity host=a;
  i.runOnMainSync(()->{host.relay.stop();host.chat.companion.select("학교 시작하기");});i.waitForIdleSync();i.check(host.chat.character.equals("grades"),"school agent owns onboarding");i.check(host.chat.companion.page.equals("대화"),"school onboarding inside chat");i.check(host.chat.messages.getChildCount()>0,"inline school card rendered");
  i.check(!SchoolSignIn.interactive("mail"),"mail never requests separate login");i.check(!SchoolSignIn.interactive("blackboard"),"Blackboard never requests separate login");i.check(SchoolSignIn.interactive("portal"),"portal remains interactive");final SchoolSignIn[] flow={null};i.runOnMainSync(()->{flow[0]=new SchoolSignIn(host.chat);flow[0].show();});i.check(flow[0].web.getVisibility()==android.view.View.INVISIBLE,"no unnecessary login before next");i.runOnMainSync(()->{flow[0].index=1;i.check(!flow[0].revealLogin(),"Blackboard login reveal rejected");i.check(flow[0].web.getVisibility()==android.view.View.INVISIBLE,"Blackboard stays invisible");flow[0].index=0;flow[0].load();i.check(flow[0].next.getVisibility()==android.view.View.GONE,"no skip or next service before authenticated evidence");i.check(flow[0].web.getImportantForAutofill()==android.view.View.IMPORTANT_FOR_AUTOFILL_YES,"login WebView supports Android Autofill");flow[0].dialog.dismiss();});i.waitForIdleSync();i.check(flow[0].closed,"cancel terminates callbacks");
  i.runOnMainSync(()->host.chat.companion.select("학교 자동화"));i.check(host.chat.companion.page.equals("대화"),"legacy workflow route resolves to chat");
  out.putString("stream","PASS "+i.checks+" school chat and SSO state checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(a!=null){final GoalAgentActivity host=a;i.runOnMainSync(host::finish);}if(!id.isEmpty())try(GoalStore s=new GoalStore(i.getTargetContext())){s.deleteGoal(id);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
